struct Continue;
impl WorkControl for Continue {
    fn charge(&mut self, _: WorkKind, _: u64) -> Result<(), Stop> {
        Ok(())
    }
    fn checkpoint(&mut self) -> Result<(), Stop> {
        Ok(())
    }
}

struct Cancel;
impl WorkControl for Cancel {
    fn charge(&mut self, _: WorkKind, _: u64) -> Result<(), Stop> {
        Err(Stop::Canceled)
    }
    fn checkpoint(&mut self) -> Result<(), Stop> {
        Err(Stop::Canceled)
    }
}

struct StopAfter(usize);
impl WorkControl for StopAfter {
    fn charge(&mut self, _: WorkKind, _: u64) -> Result<(), Stop> {
        if self.0 == 0 {
            Err(Stop::Canceled)
        } else {
            self.0 -= 1;
            Ok(())
        }
    }
    fn checkpoint(&mut self) -> Result<(), Stop> {
        if self.0 == 0 {
            Err(Stop::Canceled)
        } else {
            Ok(())
        }
    }
}

fn owner(text: &[u8]) -> SourceOwner {
    Arc::new(text.to_vec())
}

fn span(source: &[u8], value: &[u8]) -> XmlSpan {
    let offset = source
        .windows(value.len())
        .position(|part| part == value)
        .unwrap();
    XmlSpan {
        offset,
        length: value.len(),
    }
}

#[test]
fn malformed_fill_spans_are_unsupported_at_fill_offset_in_all_public_flows() {
    let bytes = b"<svg><linearGradient id='g'><stop/><stop offset='1'/></linearGradient><rect fill='url(#g)'/></svg>";
    let source = owner(bytes);
    let mut work = Continue;
    let document = LexicalDocument::parse(source.clone(), 1 << 20, &mut work).unwrap();
    let mut shared = DecodeSource::new(&document, &mut work).unwrap();
    let mut cache = PaintCache::default();
    let mut ledger = ChargeLedger::new(&source, 1 << 24, 128).unwrap();
    let edge = [Edge {
        a: Point { x: 0., y: 0. },
        b: Point { x: 1., y: 1. },
    }];
    let valid = span(bytes, b"url(#g)");
    let malformed = [
        XmlSpan {
            offset: bytes.len() + 1,
            length: 7,
        },
        XmlSpan {
            offset: valid.offset,
            length: bytes.len() - valid.offset + 1,
        },
        XmlSpan {
            offset: usize::MAX - 2,
            length: 7,
        },
        XmlSpan {
            offset: valid.offset,
            length: 0,
        },
        XmlSpan {
            offset: valid.offset,
            length: 6,
        },
    ];

    for bad in malformed {
        for flow in 0..3 {
            let prior = (
                cache.entries.len(),
                cache.slots.len(),
                cache.storage_bytes().unwrap(),
                ledger.stats(),
                ledger.work,
            );
            let result = match flow {
                0 => {
                    let mut ctx = ResolveContext {
                        shared: &mut shared,
                        cache: &mut cache,
                        ledger: &mut ledger,
                    };
                    classify_fill(&mut ctx, bad, &mut work).map(|_| ())
                }
                1 => resolve_cached_fill(
                    &mut shared,
                    &mut cache,
                    &mut ledger,
                    bad,
                    &edge,
                    affine_identity(),
                    [10., 10.],
                    &mut work,
                )
                .map(|_| ()),
                _ => {
                    let mut ctx = ResolveContext {
                        shared: &mut shared,
                        cache: &mut cache,
                        ledger: &mut ledger,
                    };
                    resolve_fill(
                        &mut ctx,
                        bad,
                        &edge,
                        affine_identity(),
                        [10., 10.],
                        &mut work,
                    )
                    .map(|_| ())
                }
            };
            let error = result.expect_err("malformed fill span must be rejected");
            assert_eq!(error.kind, ErrorKind::Unsupported);
            assert_eq!(error.offset, bad.offset);
            assert_eq!(cache.entries.len(), prior.0);
            assert_eq!(cache.slots.len(), prior.1);
            assert_eq!(cache.storage_bytes().unwrap(), prior.2);
            let after = ledger.stats();
            // Span rejection occurs before reference lookup, so only the
            // resolver's entry checkpoint may reach the job work controller.
            assert_eq!(after, prior.3);
            assert_eq!(ledger.work, prior.4);
            assert_eq!(cache.token_visits, 0);
        }
    }

    let bad = malformed[0];
    let mut cancel = Cancel;
    let cached_error = resolve_cached_fill(
        &mut shared,
        &mut cache,
        &mut ledger,
        bad,
        &edge,
        affine_identity(),
        [10., 10.],
        &mut cancel,
    )
    .unwrap_err();
    assert_eq!(cached_error.kind, ErrorKind::Canceled);
    assert_eq!(cached_error.offset, bad.offset);
    let mut ctx = ResolveContext {
        shared: &mut shared,
        cache: &mut cache,
        ledger: &mut ledger,
    };
    let owned_error = resolve_fill(
        &mut ctx,
        bad,
        &edge,
        affine_identity(),
        [10., 10.],
        &mut cancel,
    )
    .unwrap_err();
    assert_eq!(owned_error.kind, ErrorKind::Canceled);
    assert_eq!(owned_error.offset, bad.offset);

    for flow in 0..3 {
        let result = match flow {
            0 => {
                let mut ctx = ResolveContext {
                    shared: &mut shared,
                    cache: &mut cache,
                    ledger: &mut ledger,
                };
                classify_fill(&mut ctx, valid, &mut work).map(|reference| {
                    assert!(matches!(reference, PaintReference::Gradient(_)));
                })
            }
            1 => resolve_cached_fill(
                &mut shared,
                &mut cache,
                &mut ledger,
                valid,
                &edge,
                affine_identity(),
                [10., 10.],
                &mut work,
            )
            .map(|_| ()),
            _ => {
                let mut ctx = ResolveContext {
                    shared: &mut shared,
                    cache: &mut cache,
                    ledger: &mut ledger,
                };
                resolve_fill(
                    &mut ctx,
                    valid,
                    &edge,
                    affine_identity(),
                    [10., 10.],
                    &mut work,
                )
                .map(|_| ())
            }
        };
        assert!(result.is_ok(), "valid local URL span flow {flow}");
    }
}

